// ---------------------------------------------------------------------------
// B8 reinforcement: XCAF / OCAF value-type wrappers.
// Standard_GUID and TDF_Label are value types (neither Transient nor scalar).
// Same pattern as gp_Pnt: struct holds the value, Volcano side passes an
// integer object pointer, generated code reads as_gen<T>(p)->value.
// Layout assumption (deliberate, verified): each struct has exactly one member
// and no virtual functions, so static_cast from void* is equivalent to
// reinterpret_cast. Adding a second member would break this assumption.
// TDF_Label is NOT wrapped again here: the handwritten layer already has
// V3dOcafLabel (Volcano class OCCT label, object type "ocaf_label"). Reusing it
// keeps generated label pointers compatible with the handwritten class.
// ---------------------------------------------------------------------------
struct VOcctGuid { Standard_GUID value; };
struct V2dCurve { occ::handle<Geom2d_Curve> value; };
struct V2dGeometry { occ::handle<Geom2d_Geometry> value; };
struct V3dGeomCurve { occ::handle<Geom_Curve> value; };
struct V3dGeomSurface { occ::handle<Geom_Surface> value; };
struct V2dAdaptorCurve { Geom2dAdaptor_Curve value; };
struct V2dGccQCurve { std::unique_ptr<Geom2dGcc_QCurve> value; };
struct V2dApproxCurve { std::unique_ptr<Geom2dConvert_ApproxCurve> value; };
struct V2dApproxArcsSegments {
  std::unique_ptr<Geom2dAdaptor_Curve> adaptor;
  std::unique_ptr<Geom2dConvert_ApproxArcsSegments> value;
};
