class V2dBRepLibPointCloudValue : public BRepLib_PointCloudShape
{
public:
  V2dBRepLibPointCloudValue(const TopoDS_Shape& shape, double tolerance)
      : BRepLib_PointCloudShape(shape, tolerance)
  {
  }

  const std::vector<V2dBRepLibPointRecord>& Points() const { return myPoints; }

protected:
  void clear() override
  {
    BRepLib_PointCloudShape::clear();
    myPoints.clear();
  }

  void addPoint(const gp_Pnt& point, const gp_Vec& normal, const gp_Pnt2d& uv, const TopoDS_Shape& face) override
  {
    myPoints.push_back(V2dBRepLibPointRecord{point, normal, uv, face});
  }

private:
  std::vector<V2dBRepLibPointRecord> myPoints;
};
