static BRepLib_MakeShape* breplib_make_shape_from_type(void* p, const wchar_t* type)
{
  if (p == nullptr || type == nullptr) return nullptr;
  if (same_type(type, L"breplib_make_edge")) return as_breplib_make_edge(p)->value.get();
  if (same_type(type, L"breplib_make_edge2d")) return as_breplib_make_edge2d(p)->value.get();
  if (same_type(type, L"breplib_make_face")) return as_breplib_make_face(p)->value.get();
  if (same_type(type, L"breplib_make_polygon")) return as_breplib_make_polygon(p)->value.get();
  if (same_type(type, L"breplib_make_shell")) return as_breplib_make_shell(p)->value.get();
  if (same_type(type, L"breplib_make_solid")) return as_breplib_make_solid(p)->value.get();
  if (same_type(type, L"breplib_make_vertex")) return as_breplib_make_vertex(p)->value.get();
  if (same_type(type, L"breplib_make_wire")) return as_breplib_make_wire(p)->value.get();
  return nullptr;
}

static int shape_list_count(const NCollection_List<TopoDS_Shape>& shapes)
{
  int count = 0;
  for (NCollection_List<TopoDS_Shape>::Iterator it(shapes); it.More(); it.Next()) {
    ++count;
  }
  return count;
}

static void* shape_list_item(const NCollection_List<TopoDS_Shape>& shapes, int index)
{
  if (index < 1) return nullptr;
  int current = 1;
  for (NCollection_List<TopoDS_Shape>::Iterator it(shapes); it.More(); it.Next(), ++current) {
    if (current == index) return new_shape_wrapper(it.Value());
  }
  return nullptr;
}

