static std::string wide_to_utf8(const wchar_t* text)
{
  if (text == nullptr || *text == 0) return std::string();
  const int size = WideCharToMultiByte(CP_UTF8, 0, text, -1, nullptr, 0, nullptr, nullptr);
  if (size <= 1) return std::string();
  std::string result(static_cast<size_t>(size - 1), '\0');
  WideCharToMultiByte(CP_UTF8, 0, text, -1, &result[0], size, nullptr, nullptr);
  return result;
}

static TCollection_AsciiString make_ascii_string(const wchar_t* text)
{
  return TCollection_AsciiString(wide_to_utf8(text).c_str());
}

static const wchar_t* ascii_to_wide(const TCollection_AsciiString& text)
{
  static thread_local std::wstring cache;
  const char* value = text.ToCString();
  if (value == nullptr) {
    cache.clear();
    return cache.c_str();
  }
  const int size = MultiByteToWideChar(CP_UTF8, 0, value, -1, nullptr, 0);
  if (size <= 0) {
    cache.clear();
    return cache.c_str();
  }
  if (size == 1) {
    cache.clear();
    return cache.c_str();
  }
  cache.assign(static_cast<size_t>(size - 1), L'\0');
  MultiByteToWideChar(CP_UTF8, 0, value, -1, &cache[0], size);
  return cache.c_str();
}

static TopoDS_Shape make_display_compound(const std::vector<TopoDS_Shape>& shapes);

static bool parse_wide_numbers(const wchar_t* text, std::vector<double>& values)
{
  values.clear();
  if (text == nullptr) return false;
  const wchar_t* cur = text;
  while (*cur != 0) {
    wchar_t* end = nullptr;
    const double value = std::wcstod(cur, &end);
    if (end != cur) {
      values.push_back(value);
      cur = end;
    } else {
      ++cur;
    }
  }
  return !values.empty();
}

static bool build_poles_from_text(const wchar_t* text, NCollection_Array1<gp_Pnt2d>& poles)
{
  std::vector<double> values;
  if (!parse_wide_numbers(text, values) || values.size() < 4 || values.size() % 2 != 0) return false;
  const int point_count = static_cast<int>(values.size() / 2);
  if (point_count < 2 || point_count > Geom2d_BezierCurve::MaxDegree() + 1) return false;
  poles.Resize(1, point_count, false);
  for (int i = 0; i < point_count; ++i) {
    poles.SetValue(i + 1, gp_Pnt2d(values[static_cast<size_t>(i * 2)], values[static_cast<size_t>(i * 2 + 1)]));
  }
  return true;
}

static bool build_points_array_from_text(const wchar_t* text, NCollection_Array1<gp_Pnt2d>& points)
{
  std::vector<double> values;
  if (!parse_wide_numbers(text, values) || values.size() < 4 || values.size() % 2 != 0) return false;
  const int point_count = static_cast<int>(values.size() / 2);
  if (point_count < 2) return false;
  points.Resize(1, point_count, false);
  for (int i = 0; i < point_count; ++i) {
    points.SetValue(i + 1, gp_Pnt2d(values[static_cast<size_t>(i * 2)], values[static_cast<size_t>(i * 2 + 1)]));
  }
  return true;
}

static bool build_weights_from_text(const wchar_t* text, int count, NCollection_Array1<double>& weights)
{
  std::vector<double> values;
  if (!parse_wide_numbers(text, values) || static_cast<int>(values.size()) != count) return false;
  weights.Resize(1, count, false);
  for (int i = 0; i < count; ++i) {
    weights.SetValue(i + 1, values[static_cast<size_t>(i)]);
  }
  return true;
}

static occ::handle<NCollection_HArray1<gp_Pnt2d>> build_point_harray_from_text(const wchar_t* text)
{
  NCollection_Array1<gp_Pnt2d> parsed_points(1, 2);
  if (!build_points_array_from_text(text, parsed_points)) return occ::handle<NCollection_HArray1<gp_Pnt2d>>();
  occ::handle<NCollection_HArray1<gp_Pnt2d>> points = new NCollection_HArray1<gp_Pnt2d>(1, parsed_points.Length());
  for (int i = 1; i <= parsed_points.Length(); ++i) {
    points->SetValue(i, parsed_points.Value(i));
  }
  return points;
}

static occ::handle<NCollection_HArray1<double>> build_double_harray_from_text(const wchar_t* text)
{
  std::vector<double> values;
  if (!parse_wide_numbers(text, values) || values.empty()) return occ::handle<NCollection_HArray1<double>>();
  occ::handle<NCollection_HArray1<double>> result = new NCollection_HArray1<double>(1, static_cast<int>(values.size()));
  for (int i = 0; i < static_cast<int>(values.size()); ++i) {
    result->SetValue(i + 1, values[static_cast<size_t>(i)]);
  }
  return result;
}

