// ---- B8 reinforcement: Standard_GUID value-type entry points ----
// Volcano holds the wrapper pointer as an integer. A GUID can be built from
// text, converted back to text, or compared with another GUID.
extern "C" void* occt2d_guid_new(const char* text)
{
  try {
    return new VOcctGuid{ text && *text ? Standard_GUID(text) : Standard_GUID() };
  } catch (...) {
    return nullptr;
  }
}
extern "C" const char* occt2d_guid_to_string(void* g)
{
  if (!g) return nullptr;
  // ToCString writes into a caller buffer; use a thread_local static buffer
  // so the caller does not have to manage memory.
  static thread_local char buf[64];
  buf[0] = '\0';
  as_guid(g)->value.ToCString(buf);
  return buf;
}
extern "C" bool occt2d_guid_is_same(void* a, void* b)
{
  return a && b ? as_guid(a)->value.IsSame(as_guid(b)->value) : false;
}
