extern "C" double occt2d_conic_major_radius(void* conic, int kind)
{
  if (!conic) return 0.0;
  try {
    if (kind == 1) return as_elips3d(conic)->value.MajorRadius();
    if (kind == 2) return as_elips2d(conic)->value.MajorRadius();
    if (kind == 3) return as_hypr3d(conic)->value.MajorRadius();
    if (kind == 4) return as_hypr2d(conic)->value.MajorRadius();
  } catch (...) {}
  return 0.0;
}
extern "C" double occt2d_conic_minor_radius(void* conic, int kind)
{
  if (!conic) return 0.0;
  try {
    if (kind == 1) return as_elips3d(conic)->value.MinorRadius();
    if (kind == 2) return as_elips2d(conic)->value.MinorRadius();
    if (kind == 3) return as_hypr3d(conic)->value.MinorRadius();
    if (kind == 4) return as_hypr2d(conic)->value.MinorRadius();
  } catch (...) {}
  return 0.0;
}
extern "C" double occt2d_conic_focal(void* conic, int kind)
{
  if (!conic) return 0.0;
  try {
    if (kind == 1) return as_elips3d(conic)->value.Focal();
    if (kind == 2) return as_elips2d(conic)->value.Focal();
    if (kind == 3) return as_hypr3d(conic)->value.Focal();
    if (kind == 4) return as_hypr2d(conic)->value.Focal();
    if (kind == 5) return as_parab3d(conic)->value.Focal();
    if (kind == 6) return as_parab2d(conic)->value.Focal();
  } catch (...) {}
  return 0.0;
}
