extern "C" void* occt2d_pequation_new_from_text(const wchar_t* points_text, double tolerance)
{
  std::vector<double> values;
  if (!parse_wide_numbers(points_text, values) || values.size() < 3 || values.size() % 3 != 0) return nullptr;
  try {
    const int count = static_cast<int>(values.size() / 3);
    NCollection_Array1<gp_Pnt> points(1, count);
    for (int i = 0; i < count; ++i) {
      points.SetValue(i + 1, gp_Pnt(values[static_cast<size_t>(i * 3)], values[static_cast<size_t>(i * 3 + 1)], values[static_cast<size_t>(i * 3 + 2)]));
    }
    VOcctPEquation* result = new VOcctPEquation{};
    result->value = std::make_unique<GProp_PEquation>(points, tolerance);
    return result;
  } catch (...) { return nullptr; }
}
