static double lin2d_coefficient(void* line, int index)
{
  if (!line) return 0.0;
  try {
    double a = 0.0;
    double b = 0.0;
    double c = 0.0;
    as_lin(line)->value.Coefficients(a, b, c);
    return index == 1 ? a : (index == 2 ? b : c);
  } catch (...) {
    return 0.0;
  }
}

extern "C" double occt2d_lin2d_coefficient_a(void* line) { return lin2d_coefficient(line, 1); }
extern "C" double occt2d_lin2d_coefficient_b(void* line) { return lin2d_coefficient(line, 2); }
extern "C" double occt2d_lin2d_coefficient_c(void* line) { return lin2d_coefficient(line, 3); }

