extern "C" double occt2d_circ2d_coefficient(void* circle, int index)
{
  if (!circle || index < 1 || index > 6) return 0.0;
  try {
    double a = 0.0, b = 0.0, c = 0.0, d = 0.0, e = 0.0, f = 0.0;
    as_circ2d(circle)->value.Coefficients(a, b, c, d, e, f);
    switch (index) {
    case 1: return a;
    case 2: return b;
    case 3: return c;
    case 4: return d;
    case 5: return e;
    case 6: return f;
    default: return 0.0;
    }
  } catch (...) {
    return 0.0;
  }
}

