extern "C" const wchar_t* occt2d_line_dump_json(void* line, int depth)
{
  static thread_local std::wstring cache;
  cache.clear();
  if (line == nullptr) return cache.c_str();
  try {
    occ::handle<Geom2d_Line> l = as_line_curve(line);
    if (l.IsNull()) return cache.c_str();
    std::ostringstream out;
    l->DumpJson(out, depth);
    const std::string text = out.str();
    cache.assign(text.begin(), text.end());
    return cache.c_str();
  } catch (...) {
    cache.clear();
    return cache.c_str();
  }
}

