extern "C" void* occt2d_bezier4_new(double x1, double y1, double x2, double y2, double x3, double y3, double x4, double y4)
{
  try {
  NCollection_Array1<gp_Pnt2d> poles(1, 4);
  poles.SetValue(1, gp_Pnt2d(x1, y1));
  poles.SetValue(2, gp_Pnt2d(x2, y2));
  poles.SetValue(3, gp_Pnt2d(x3, y3));
  poles.SetValue(4, gp_Pnt2d(x4, y4));
  V2dCurve* c = new V2dCurve;
  c->value = new Geom2d_BezierCurve(poles);
  return c;
  } catch (...) { return nullptr; }
}

extern "C" void* occt2d_bezier_new_from_text(const wchar_t* points_text)
{
  try {
    NCollection_Array1<gp_Pnt2d> poles(1, 2);
    if (!build_poles_from_text(points_text, poles)) return nullptr;
    return new V2dCurve{new Geom2d_BezierCurve(poles)};
  } catch (...) {
    return nullptr;
  }
}

extern "C" void* occt2d_bezier_new_from_text_weights(const wchar_t* points_text, const wchar_t* weights_text)
{
  try {
    NCollection_Array1<gp_Pnt2d> poles(1, 2);
    if (!build_poles_from_text(points_text, poles)) return nullptr;
    NCollection_Array1<double> weights(1, poles.Length());
    if (!build_weights_from_text(weights_text, poles.Length(), weights)) return nullptr;
    return new V2dCurve{new Geom2d_BezierCurve(poles, weights)};
  } catch (...) {
    return nullptr;
  }
}

