extern "C" const wchar_t* occt2d_bezier_dump_json(void* bezier, int depth)
{
  static thread_local std::wstring cache;
  cache.clear();
  try {
    occ::handle<Geom2d_BezierCurve> b = as_bezier_curve(bezier);
    if (b.IsNull()) return cache.c_str();
    std::ostringstream out;
    b->DumpJson(out, depth);
    const std::string text = out.str();
    cache.assign(text.begin(), text.end());
    return cache.c_str();
  } catch (...) {
    cache.clear();
    return cache.c_str();
  }
}

extern "C" void* occt2d_bspline_new_from_text(const wchar_t* points_text, int degree)
{
  try {
    NCollection_Array1<gp_Pnt2d> poles(1, 2);
    if (!build_poles_from_text(points_text, poles)) return nullptr;
    if (degree < 1 || degree > Geom2d_BSplineCurve::MaxDegree()) return nullptr;
    if (poles.Length() <= degree) return nullptr;

    const int knot_count = poles.Length() - degree + 1;
    if (knot_count < 2) return nullptr;
    NCollection_Array1<double> knots(1, knot_count);
    NCollection_Array1<int> mults(1, knot_count);
    for (int i = 1; i <= knot_count; ++i) {
      knots.SetValue(i, static_cast<double>(i - 1));
      mults.SetValue(i, (i == 1 || i == knot_count) ? degree + 1 : 1);
    }
    return new V2dCurve{new Geom2d_BSplineCurve(poles, knots, mults, degree, false)};
  } catch (...) {
    return nullptr;
  }
}

