extern "C" void* occt2d_points_to_bspline_new(const wchar_t* points_text, int deg_min, int deg_max, int continuity, double tolerance)
{
  try {
    NCollection_Array1<gp_Pnt2d> points(1, 2);
    if (!build_points_array_from_text(points_text, points)) return nullptr;
    V2dPointsToBSpline* result = new V2dPointsToBSpline;
    result->value.Init(points, deg_min, deg_max, static_cast<GeomAbs_Shape>(continuity), tolerance);
    return result;
  } catch (...) { return nullptr; }
}

extern "C" void* occt2d_points_to_bspline_new_parameters(const wchar_t* points_text, const wchar_t* parameters_text, int deg_min, int deg_max, int continuity, double tolerance)
{
  try {
    NCollection_Array1<gp_Pnt2d> points(1, 2);
    if (!build_points_array_from_text(points_text, points)) return nullptr;
    std::vector<double> values;
    if (!parse_wide_numbers(parameters_text, values) || static_cast<int>(values.size()) != points.Length()) return nullptr;
    NCollection_Array1<double> params(1, points.Length());
    for (int i = 0; i < points.Length(); ++i) params.SetValue(i + 1, values[static_cast<size_t>(i)]);
    V2dPointsToBSpline* result = new V2dPointsToBSpline;
    result->value.Init(points, params, deg_min, deg_max, static_cast<GeomAbs_Shape>(continuity), tolerance);
    return result;
  } catch (...) { return nullptr; }
}

