extern "C" void* occt2d_interpolate_new(const wchar_t* points_text, bool periodic, double tolerance)
{
  try {
    occ::handle<NCollection_HArray1<gp_Pnt2d>> points = build_point_harray_from_text(points_text);
    if (points.IsNull()) return nullptr;
    V2dInterpolate* result = new V2dInterpolate;
    result->points = points;
    result->has_parameters = false;
    result->periodic = periodic;
    result->tolerance = tolerance;
    result->value.reset(new Geom2dAPI_Interpolate(points, periodic, tolerance));
    return result;
  } catch (...) { return nullptr; }
}

extern "C" void* occt2d_interpolate_new_parameters(const wchar_t* points_text, const wchar_t* parameters_text, bool periodic, double tolerance)
{
  try {
    occ::handle<NCollection_HArray1<gp_Pnt2d>> points = build_point_harray_from_text(points_text);
    occ::handle<NCollection_HArray1<double>> params = build_double_harray_from_text(parameters_text);
    if (points.IsNull() || params.IsNull()) return nullptr;
    V2dInterpolate* result = new V2dInterpolate;
    result->points = points;
    result->parameters = params;
    result->has_parameters = true;
    result->periodic = periodic;
    result->tolerance = tolerance;
    result->value.reset(new Geom2dAPI_Interpolate(points, params, periodic, tolerance));
    return result;
  } catch (...) { return nullptr; }
}

extern "C" bool occt2d_interpolate_load_end_tangents(void* interpolation, void* start_vec, void* end_vec, bool scale)
{
  try {
    if (interpolation == nullptr || !as_interpolate(interpolation)->value || start_vec == nullptr || end_vec == nullptr) return false;
    as_interpolate(interpolation)->value->Load(as_vec(start_vec)->value, as_vec(end_vec)->value, scale);
    return true;
  } catch (...) { return false; }
}

extern "C" bool occt2d_interpolate_clear_tangents(void* interpolation)
{
  try {
    if (interpolation == nullptr || !as_interpolate(interpolation)->value) return false;
    V2dInterpolate* inter = as_interpolate(interpolation);
    if (inter->points.IsNull()) return false;
    if (inter->has_parameters) {
      if (inter->parameters.IsNull()) return false;
      inter->value.reset(new Geom2dAPI_Interpolate(inter->points, inter->parameters, inter->periodic, inter->tolerance));
    } else {
      inter->value.reset(new Geom2dAPI_Interpolate(inter->points, inter->periodic, inter->tolerance));
    }
    return true;
  } catch (...) { return false; }
}

extern "C" bool occt2d_interpolate_perform(void* interpolation)
{
  try {
    if (interpolation == nullptr || !as_interpolate(interpolation)->value) return false;
    as_interpolate(interpolation)->value->Perform();
    return as_interpolate(interpolation)->value->IsDone();
  } catch (...) { return false; }
}

