static void gcc_lin2d2tan_tangency(void* algo, int index, int which, double* par_sol, double* par_arg, void** point)
{
  if (point) *point = nullptr;
  if (par_sol) *par_sol = 0.0;
  if (par_arg) *par_arg = 0.0;
  if (!algo || !as_gcc_lin2d2tan(algo)->value || !par_sol || !par_arg || !point) return;
  try {
    gp_Pnt2d p;
    if (which == 1) as_gcc_lin2d2tan(algo)->value->Tangency1(index, *par_sol, *par_arg, p);
    else as_gcc_lin2d2tan(algo)->value->Tangency2(index, *par_sol, *par_arg, p);
    *point = make_v2d_point_from_gp(p);
  } catch (...) {}
}

extern "C" void* occt2d_gcc_lin2d2tan_tangency1_point(void* algo, int index)
{
  double ps = 0.0, pa = 0.0; void* p = nullptr; gcc_lin2d2tan_tangency(algo, index, 1, &ps, &pa, &p); return p;
}

extern "C" void* occt2d_gcc_lin2d2tan_tangency2_point(void* algo, int index)
{
  double ps = 0.0, pa = 0.0; void* p = nullptr; gcc_lin2d2tan_tangency(algo, index, 2, &ps, &pa, &p); return p;
}

