template <class CurveT>
static void* make_curve_wrapper(const occ::handle<CurveT>& curve)
{
  if (curve.IsNull()) return nullptr;
  return new V2dCurve{occ::handle<Geom2d_Curve>::DownCast(curve)};
}

static void* make_geometry_wrapper(const occ::handle<Geom2d_Geometry>& geometry)
{
  return geometry.IsNull() ? nullptr : new V2dGeometry{geometry};
}

template <class WrapperT, class CurveT>
static void* tcol_array_new(int lower, int upper)
{
  try {
    if (upper < lower) return nullptr;
    auto* wrapper = new WrapperT;
    wrapper->value.reset(new NCollection_Array1<occ::handle<CurveT>>(lower, upper));
    return wrapper;
  } catch (...) { return nullptr; }
}

template <class WrapperT>
static int tcol_array_lower(void* array)
{
  try { return array && static_cast<WrapperT*>(array)->value ? static_cast<WrapperT*>(array)->value->Lower() : 0; } catch (...) { return 0; }
}

template <class WrapperT>
static int tcol_array_upper(void* array)
{
  try { return array && static_cast<WrapperT*>(array)->value ? static_cast<WrapperT*>(array)->value->Upper() : 0; } catch (...) { return 0; }
}

template <class WrapperT>
static int tcol_array_length(void* array)
{
  try { return array && static_cast<WrapperT*>(array)->value ? static_cast<WrapperT*>(array)->value->Length() : 0; } catch (...) { return 0; }
}

template <class WrapperT, class CurveT>
static void* tcol_array_value(void* array, int index)
{
  try {
    if (!array || !static_cast<WrapperT*>(array)->value) return nullptr;
    return make_curve_wrapper(static_cast<WrapperT*>(array)->value->Value(index));
  } catch (...) { return nullptr; }
}

template <class WrapperT, class CurveT>
static bool tcol_array_set(void* array, int index, void* curve)
{
  try {
    if (!array || !static_cast<WrapperT*>(array)->value) return false;
    occ::handle<CurveT> value = curve_handle_from_wrapper<CurveT>(curve);
    if (value.IsNull()) return false;
    static_cast<WrapperT*>(array)->value->SetValue(index, value);
    return true;
  } catch (...) { return false; }
}

