extern "C" bool occt2d_viewer_display_test_grid(void* viewer, double width, double height, double step)
{
  if (viewer == nullptr || width <= 0.0 || height <= 0.0 || step <= 0.0) return false;
  try {
    std::vector<TopoDS_Shape> grid_shapes;
    for (double x = 0.0; x <= width + step * 0.5; x += step) {
      grid_shapes.push_back(BRepBuilderAPI_MakeEdge(gp_Pnt(x, 0.0, 0.0), gp_Pnt(x, height, 0.0)).Shape());
    }
    for (double y = 0.0; y <= height + step * 0.5; y += step) {
      grid_shapes.push_back(BRepBuilderAPI_MakeEdge(gp_Pnt(0.0, y, 0.0), gp_Pnt(width, y, 0.0)).Shape());
    }
    return display_shape(as_viewer(viewer), make_display_compound(grid_shapes), 210, 210, 210, 1.0);
  } catch (...) {
    return false;
  }
}

