extern "C" bool occt2d_viewer_zoom_factor(void* viewer, double factor)
{
  if (viewer == nullptr || factor <= 0.0 || !std::isfinite(factor)) return false;
  try {
    V2dViewer* v = as_viewer(viewer);
    const double old_scale = v->view->Scale();
    if (old_scale <= 0.0 || !std::isfinite(old_scale)) return false;
    v->view->SetScale(old_scale / factor);
    v->view->Redraw();
    return true;
  } catch (...) {
    return false;
  }
}

