extern "C" bool occt2d_window_design_display(void* design, void* viewer, int edge_red, int edge_green, int edge_blue, int fill_red, int fill_green, int fill_blue, int selected_red, int selected_green, int selected_blue, double width, int line_type, bool fill_enabled)
{
  try {
    if (design == nullptr || viewer == nullptr) return false;
    V2dWindowDesign* d = as_window_design(design);
    V2dViewer* v = as_viewer(viewer);
    bool ok = true;
    if (fill_enabled) {
      const TopoDS_Shape face = window_design_face(d);
      if (!face.IsNull()) ok = display_shape_mode(v, face, fill_red, fill_green, fill_blue, 1.0, AIS_Shaded) && ok;
    }
    const TopoDS_Shape normal = window_design_compound(d, false, true);
    if (!normal.IsNull()) ok = display_shape_style(v, normal, edge_red, edge_green, edge_blue, width, line_type) && ok;
    const TopoDS_Shape selected = window_design_compound(d, true, false);
    if (!selected.IsNull()) {
      const double selected_width = width > 0.0 ? width + 2.0 : 3.0;
      ok = display_shape_style(v, selected, selected_red, selected_green, selected_blue, selected_width, Aspect_TOL_SOLID) && ok;
    }
    return ok;
  } catch (...) {
    return false;
  }
}

