extern "C" bool occt2d_v3d_viewer_display_test_grid(void* viewer, void* view, double width, double height, double step)
{
  if (viewer == nullptr || view == nullptr || step <= 0.0 || width <= 0.0 || height <= 0.0) return false;
  try {
    std::vector<TopoDS_Shape> grid_shapes;
    for (double x = 0.0; x <= width + 0.0001; x += step) {
      grid_shapes.push_back(BRepBuilderAPI_MakeEdge(gp_Pnt(x, 0.0, 0.0), gp_Pnt(x, height, 0.0)).Shape());
    }
    for (double y = 0.0; y <= height + 0.0001; y += step) {
      grid_shapes.push_back(BRepBuilderAPI_MakeEdge(gp_Pnt(0.0, y, 0.0), gp_Pnt(width, y, 0.0)).Shape());
    }
    grid_shapes.push_back(BRepBuilderAPI_MakeEdge(gp_Pnt(0.0, 0.0, 0.0), gp_Pnt(width, height, 0.0)).Shape());
    grid_shapes.push_back(BRepBuilderAPI_MakeEdge(gp_Pnt(0.0, height, 0.0), gp_Pnt(width, 0.0, 0.0)).Shape());
    return display_low_level_shape(as_v3d_viewer(viewer), as_v3d_view(view), make_display_compound(grid_shapes), 38, 110, 190, 1.5);
  } catch (...) {
    return false;
  }
}

extern "C" bool occt2d_v3d_viewer_display_edge(void* viewer, void* view, void* edge, int red, int green, int blue, double width)
{
  if (viewer == nullptr || view == nullptr || edge == nullptr) return false;
  try {
    const TopoDS_Shape shape = !as_edge(edge)->display_shape.IsNull() ? as_edge(edge)->display_shape : TopoDS_Shape(as_edge(edge)->edge);
    return display_low_level_shape(as_v3d_viewer(viewer), as_v3d_view(view), shape, red, green, blue, width);
  } catch (...) {
    return false;
  }
}

extern "C" bool occt2d_v3d_viewer_display_wire(void* viewer, void* view, void* wire, int red, int green, int blue, double width)
{
  if (viewer == nullptr || view == nullptr || wire == nullptr) return false;
  try {
    TopoDS_Shape shape;
    if (!as_wire(wire)->display_shapes.empty()) {
      shape = make_display_compound(as_wire(wire)->display_shapes);
    } else if (!as_wire(wire)->wire.IsNull()) {
      shape = TopoDS_Shape(as_wire(wire)->wire);
    }
    return display_low_level_shape(as_v3d_viewer(viewer), as_v3d_view(view), shape, red, green, blue, width);
  } catch (...) {
    return false;
  }
}

