extern "C" void* occt2d_wnt_window_new(void* host_hwnd)
{
  if (host_hwnd == nullptr) return nullptr;
  try {
    V2dWntWindow* window = new V2dWntWindow;
    window->host_hwnd = reinterpret_cast<HWND>(host_hwnd);
    window->render_hwnd = create_occt2d_render_child(window->host_hwnd);
    if (window->render_hwnd == nullptr) {
      delete window;
      return nullptr;
    }
    window->value = new WNT_Window(reinterpret_cast<Aspect_Handle>(window->render_hwnd));
    return window;
  } catch (...) {
    return nullptr;
  }
}

