extern "C" bool occt2d_wnt_window_resize(void* window)
{
  if (window == nullptr) return false;
  try {
    V2dWntWindow* w = as_wnt_window(window);
    if (w->host_hwnd == nullptr || w->render_hwnd == nullptr) return false;
    RECT rc;
    GetClientRect(w->host_hwnd, &rc);
    SetWindowPos(w->render_hwnd, nullptr, 0, 0, rc.right - rc.left, rc.bottom - rc.top, SWP_NOZORDER | SWP_NOACTIVATE);
    return true;
  } catch (...) {
    return false;
  }
}

