extern "C" bool occt2d_v3d_view_set_window(void* view, void* window)
{
  if (view == nullptr || window == nullptr || as_v3d_view(view)->value.IsNull() || as_wnt_window(window)->value.IsNull()) return false;
  try {
    as_v3d_view(view)->value->SetWindow(as_wnt_window(window)->value);
    if (!as_wnt_window(window)->value->IsMapped()) {
      as_wnt_window(window)->value->Map();
    }
    as_v3d_view(view)->value->MustBeResized();
    as_v3d_view(view)->value->Redraw();
    return true;
  } catch (...) {
    return false;
  }
}

extern "C" bool occt2d_v3d_view_set_2d_projection(void* view)
{
  if (view == nullptr || as_v3d_view(view)->value.IsNull()) return false;
  try {
    occ::handle<V3d_View> v = as_v3d_view(view)->value;
    v->SetProj(V3d_Zpos, false);
    v->SetUp(0.0, 1.0, 0.0);
    v->SetViewOrientationDefault();
    if (!v->Camera().IsNull()) {
      v->Camera()->SetProjectionType(Graphic3d_Camera::Projection_Orthographic);
    }
    v->Redraw();
    return true;
  } catch (...) {
    return false;
  }
}

