extern "C" bool occt2d_v3d_view_zoom_factor(void* view, double factor)
{
  if (view == nullptr || as_v3d_view(view)->value.IsNull() || factor <= 0.0 || !std::isfinite(factor)) return false;
  try {
    const double old_scale = as_v3d_view(view)->value->Scale();
    if (old_scale <= 0.0 || !std::isfinite(old_scale)) return false;
    as_v3d_view(view)->value->SetScale(old_scale / factor);
    as_v3d_view(view)->value->Redraw();
    return true;
  } catch (...) {
    return false;
  }
}

