extern "C" bool occt2d_v3d_view_dump(void* view, const wchar_t* path, int buffer_type)
{
  try {
    if (view == nullptr || path == nullptr || *path == 0 || as_v3d_view(view)->value.IsNull()) return false;
    const std::string file_name = wide_to_utf8(path);
    if (file_name.empty()) return false;
    return as_v3d_view(view)->value->Dump(file_name.c_str(), static_cast<Graphic3d_BufferType>(buffer_type));
  } catch (...) { return false; }
}

extern "C" bool occt2d_v3d_view_dump_options(void* view, const wchar_t* path, void* options)
{
  try {
    if (view == nullptr || path == nullptr || *path == 0 || options == nullptr || as_v3d_view(view)->value.IsNull()) return false;
    const std::string file_name = wide_to_utf8(path);
    if (file_name.empty()) return false;
    V3d_ImageDumpOptions& opts = as_v3d_dump_options(options)->value;
    if (opts.Width <= 0 || opts.Height <= 0) {
      return as_v3d_view(view)->value->Dump(file_name.c_str(), opts.BufferType);
    }
    Image_AlienPixMap image;
    if (!as_v3d_view(view)->value->ToPixMap(image, opts)) return false;
    return image.Save(TCollection_AsciiString(file_name.c_str()));
  } catch (...) { return false; }
}

