extern "C" int occt2d_v3d_light_color_component(void* light, int component)
{
  try {
    if (light == nullptr || as_v3d_light(light)->value.IsNull()) return 0;
    const Quantity_Color& c = as_v3d_light(light)->value->Color();
    const double value = component == 0 ? c.Red() : (component == 1 ? c.Green() : c.Blue());
    return clamp_color(static_cast<int>(value * 255.0 + 0.5));
  } catch (...) { return 0; }
}

