extern "C" bool occt2d_v3d_light_set_direction_orientation(void* light, int orientation)
{
  try {
    if (light == nullptr || as_v3d_light(light)->value.IsNull()) return false;
    occ::handle<V3d_DirectionalLight> dir = occ::handle<V3d_DirectionalLight>::DownCast(as_v3d_light(light)->value);
    if (!dir.IsNull()) { dir->SetDirection(static_cast<V3d_TypeOfOrientation>(orientation)); return true; }
    occ::handle<V3d_SpotLight> spot = occ::handle<V3d_SpotLight>::DownCast(as_v3d_light(light)->value);
    if (!spot.IsNull()) { spot->SetDirection(static_cast<V3d_TypeOfOrientation>(orientation)); return true; }
    return false;
  } catch (...) { return false; }
}

