extern "C" const wchar_t* occt2d_ais_context_dump_json(void* context, int depth)
{
  static thread_local std::wstring cache;
  cache.clear();
  try {
    if (context == nullptr || as_ais_context(context)->value.IsNull()) return cache.c_str();
    std::ostringstream out;
    as_ais_context(context)->value->DumpJson(out, depth);
    const std::string text = out.str();
    cache.assign(text.begin(), text.end());
    return cache.c_str();
  } catch (...) {
    cache.clear();
    return cache.c_str();
  }
}

