extern "C" const wchar_t* occt2d_ais_animation_name(void* animation)
{
  static thread_local std::wstring cache;
  cache.clear();
  try {
    occ::handle<AIS_Animation> anim = as_animation_handle(animation);
    if (anim.IsNull()) return cache.c_str();
    const std::string text = anim->Name().ToCString();
    cache.assign(text.begin(), text.end());
    return cache.c_str();
  } catch (...) {
    cache.clear();
    return cache.c_str();
  }
}

