extern "C" bool occt2d_ais_view_controller_set_allow(void* controller, int option, bool value)
{
  try {
    if (controller == nullptr || !as_ais_view_controller(controller)->value) return false;
    AIS_ViewController* ctl = as_ais_view_controller(controller)->value.get();
    if (option == 1) ctl->SetAllowRotation(value);
    else if (option == 2) ctl->SetAllowPanning(value);
    else if (option == 3) ctl->SetAllowZooming(value);
    else if (option == 4) ctl->SetAllowHighlight(value);
    else if (option == 5) ctl->SetAllowDragging(value);
    else return false;
    return true;
  } catch (...) { return false; }
}

extern "C" bool occt2d_ais_view_controller_allow(void* controller, int option)
{
  try {
    if (controller == nullptr || !as_ais_view_controller(controller)->value) return false;
    AIS_ViewController* ctl = as_ais_view_controller(controller)->value.get();
    if (option == 1) return ctl->ToAllowRotation();
    if (option == 2) return ctl->ToAllowPanning();
    if (option == 3) return ctl->ToAllowZooming();
    if (option == 4) return ctl->ToAllowHighlight();
    if (option == 5) return ctl->ToAllowDragging();
    return false;
  } catch (...) { return false; }
}

