extern "C" bool occt2d_ais_point_cloud_set_points_text(void* cloud, const wchar_t* points_text)
{
  try {
    if (cloud == nullptr || as_ais_point_cloud(cloud)->value.IsNull()) return false;
    std::vector<double> values;
    if (!parse_wide_numbers(points_text, values) || values.size() < 3 || (values.size() % 3) != 0) return false;
    const int count = static_cast<int>(values.size() / 3);
    occ::handle<Graphic3d_ArrayOfPoints> points = new Graphic3d_ArrayOfPoints(count, false, false);
    for (int i = 0; i < count; ++i) {
      points->AddVertex(values[static_cast<size_t>(i) * 3], values[static_cast<size_t>(i) * 3 + 1], values[static_cast<size_t>(i) * 3 + 2]);
    }
    as_ais_point_cloud(cloud)->value->SetPoints(points);
    return true;
  } catch (...) { return false; }
}

extern "C" int occt2d_ais_point_cloud_count(void* cloud)
{
  try {
    if (cloud == nullptr || as_ais_point_cloud(cloud)->value.IsNull()) return 0;
    occ::handle<Graphic3d_ArrayOfPoints> points = as_ais_point_cloud(cloud)->value->GetPoints();
    return points.IsNull() ? 0 : points->VertexNumber();
  } catch (...) { return 0; }
}

