extern "C" const wchar_t* occt2d_ais_text_label_text(void* label)
{
  static thread_local std::wstring cache;
  cache.clear();
  try {
    if (label == nullptr || as_ais_text_label(label)->value.IsNull()) return cache.c_str();
    cache.assign(as_ais_text_label(label)->value->Text().ToWideString());
    return cache.c_str();
  } catch (...) { cache.clear(); return cache.c_str(); }
}

