extern "C" void* occt2d_geom_curve3d_from_edge(void* edge)
{
  try {
    if (edge == nullptr || as_edge(edge)->edge.IsNull()) return nullptr;
    double first = 0.0, last = 0.0;
    occ::handle<Geom_Curve> curve = BRep_Tool::Curve(as_edge(edge)->edge, first, last);
    return curve.IsNull() ? nullptr : new V3dGeomCurve{curve};
  } catch (...) { return nullptr; }
}

