extern "C" const wchar_t* occt2d_shape_dump_json(void* shape, int depth)
{
  static thread_local std::wstring cache;
  cache.clear();
  try {
    if (shape == nullptr || as_shape(shape)->shape.IsNull()) return cache.c_str();
    std::ostringstream out;
    as_shape(shape)->shape.DumpJson(out, depth);
    const std::string text = out.str();
    cache.assign(text.begin(), text.end());
    return cache.c_str();
  } catch (...) {
    cache.clear();
    return cache.c_str();
  }
}

