static const wchar_t* h_ascii_to_wide(const occ::handle<TCollection_HAsciiString>& text)
{
  static thread_local std::wstring cache;
  cache.clear();
  if (text.IsNull()) return cache.c_str();
  const char* value = text->ToCString();
  if (value == nullptr) return cache.c_str();
  const std::string narrow(value);
  cache.assign(narrow.begin(), narrow.end());
  return cache.c_str();
}

