static NCollection_List<TopoDS_Shape> brep_shape_list(void* shape1, void* shape2, bool has_shape2)
{
  NCollection_List<TopoDS_Shape> list;
  if (shape1 != nullptr && !as_shape(shape1)->shape.IsNull()) list.Append(as_shape(shape1)->shape);
  if (has_shape2 && shape2 != nullptr && !as_shape(shape2)->shape.IsNull()) list.Append(as_shape(shape2)->shape);
  return list;
}

static int brep_shape_list_count(const NCollection_List<TopoDS_Shape>& list)
{
  return list.Size();
}

static void* brep_shape_list_value(const NCollection_List<TopoDS_Shape>& list, int index)
{
  if (index < 1 || index > list.Size()) return nullptr;
  int current = 1;
  for (NCollection_List<TopoDS_Shape>::Iterator it(list); it.More(); it.Next(), ++current) {
    if (current == index) return new_shape_wrapper(it.Value());
  }
  return nullptr;
}

static BRepAlgoAPI_Algo* brepalgo_algo_ptr(void* command, const wchar_t* type)
{
  if (command == nullptr || type == nullptr) return nullptr;
  if (same_type(type, L"brepalgo_boolean")) return as_brepalgo_boolean(command)->value.get();
  if (same_type(type, L"brepalgo_common")) return as_brepalgo_common(command)->value.get();
  if (same_type(type, L"brepalgo_cut")) return as_brepalgo_cut(command)->value.get();
  if (same_type(type, L"brepalgo_defeaturing")) return as_brepalgo_defeaturing(command)->value.get();
  if (same_type(type, L"brepalgo_fuse")) return as_brepalgo_fuse(command)->value.get();
  if (same_type(type, L"brepalgo_section")) return as_brepalgo_section(command)->value.get();
  if (same_type(type, L"brepalgo_splitter")) return as_brepalgo_splitter(command)->value.get();
  return nullptr;
}

