static BRepBuilderAPI_Command* brep_command_ptr(void* command, const wchar_t* type)
{
  if (command == nullptr || type == nullptr) return nullptr;
  if (BRepAlgoAPI_Algo* value = brepalgo_algo_ptr(command, type)) return value;
  if (same_type(type, L"brep_copy") || same_type(type, L"copy")) return as_brep_copy(command)->value.get();
  if (same_type(type, L"brep_transform") || same_type(type, L"transform")) return as_brep_transform(command)->value.get();
  if (same_type(type, L"brep_gtransform") || same_type(type, L"gtransform")) return as_brep_gtransform(command)->value.get();
  if (same_type(type, L"brep_make_edge")) return as_brep_make_edge(command)->value.get();
  if (same_type(type, L"brep_make_face")) return as_brep_make_face(command)->value.get();
  if (same_type(type, L"brep_make_polygon")) return as_brep_make_polygon(command)->value.get();
  if (same_type(type, L"brep_make_shape_on_mesh")) return as_brep_make_shape_on_mesh(command)->value.get();
  if (same_type(type, L"brep_make_shell")) return as_brep_make_shell(command)->value.get();
  if (same_type(type, L"brep_make_solid")) return as_brep_make_solid(command)->value.get();
  if (same_type(type, L"brep_make_vertex")) return as_brep_make_vertex(command)->value.get();
  if (same_type(type, L"brep_nurbs_convert") || same_type(type, L"nurbs_convert")) return as_brep_nurbs_convert(command)->value.get();
  return nullptr;
}

