extern "C" void* occt2d_brep_modifyshape_modified_shape(void* command, const wchar_t* type, void* shape)
{
  try {
    if (shape == nullptr || as_shape(shape)->shape.IsNull()) return nullptr;
    if (command == nullptr || type == nullptr) return nullptr;
    if (same_type(type, L"brep_copy") || same_type(type, L"copy")) return new_shape_wrapper(as_brep_copy(command)->value->ModifiedShape(as_shape(shape)->shape));
    if (same_type(type, L"brep_transform") || same_type(type, L"transform")) return new_shape_wrapper(as_brep_transform(command)->value->ModifiedShape(as_shape(shape)->shape));
    if (same_type(type, L"brep_gtransform") || same_type(type, L"gtransform")) return new_shape_wrapper(as_brep_gtransform(command)->value->ModifiedShape(as_shape(shape)->shape));
    if (same_type(type, L"brep_nurbs_convert") || same_type(type, L"nurbs_convert")) return new_shape_wrapper(as_brep_nurbs_convert(command)->value->ModifiedShape(as_shape(shape)->shape));
    return nullptr;
  } catch (...) { return nullptr; }
}

