extern "C" const wchar_t* occt2d_breplib_edge_error_name(int error)
{
  switch (static_cast<BRepLib_EdgeError>(error)) {
    case BRepLib_EdgeDone: return L"EdgeDone";
    case BRepLib_PointProjectionFailed: return L"PointProjectionFailed";
    case BRepLib_ParameterOutOfRange: return L"ParameterOutOfRange";
    case BRepLib_DifferentPointsOnClosedCurve: return L"DifferentPointsOnClosedCurve";
    case BRepLib_PointWithInfiniteParameter: return L"PointWithInfiniteParameter";
    case BRepLib_DifferentsPointAndParameter: return L"DifferentsPointAndParameter";
    case BRepLib_LineThroughIdenticPoints: return L"LineThroughIdenticPoints";
  }
  return L"Unknown";
}

