extern "C" void* occt2d_breplib_make_wire_from_edges(void* e1, void* e2, void* e3, void* e4, int count)
{
  try {
    if (e1 == nullptr || as_shape(e1)->shape.IsNull()) return nullptr;
    V2dBRepLibMakeWire* wrapper = new V2dBRepLibMakeWire;
    if (count <= 1 || e2 == nullptr || as_shape(e2)->shape.IsNull()) {
      wrapper->value = std::make_unique<BRepLib_MakeWire>(TopoDS::Edge(as_shape(e1)->shape));
    } else if (count == 2 || e3 == nullptr || as_shape(e3)->shape.IsNull()) {
      wrapper->value = std::make_unique<BRepLib_MakeWire>(TopoDS::Edge(as_shape(e1)->shape), TopoDS::Edge(as_shape(e2)->shape));
    } else if (count == 3 || e4 == nullptr || as_shape(e4)->shape.IsNull()) {
      wrapper->value = std::make_unique<BRepLib_MakeWire>(TopoDS::Edge(as_shape(e1)->shape), TopoDS::Edge(as_shape(e2)->shape), TopoDS::Edge(as_shape(e3)->shape));
    } else {
      wrapper->value = std::make_unique<BRepLib_MakeWire>(TopoDS::Edge(as_shape(e1)->shape), TopoDS::Edge(as_shape(e2)->shape), TopoDS::Edge(as_shape(e3)->shape), TopoDS::Edge(as_shape(e4)->shape));
    }
    return wrapper;
  } catch (...) { return nullptr; }
}

