extern "C" void* occt2d_brep_sewing_contiguous_edge_couple_shape(void* sewing, int index, int shape_index)
{
  try {
    if (sewing == nullptr || as_brep_sewing(sewing)->value.IsNull() || shape_index < 1) return nullptr;
    const NCollection_List<TopoDS_Shape>& shapes = as_brep_sewing(sewing)->value->ContigousEdgeCouple(index);
    int current = 1;
    for (NCollection_List<TopoDS_Shape>::Iterator it(shapes); it.More(); it.Next(), ++current) {
      if (current == shape_index) return new_shape_wrapper(it.Value());
    }
    return nullptr;
  } catch (...) { return nullptr; }
}

