static bool write_brep_shape(const TopoDS_Shape& shape, const wchar_t* path)
{
  if (shape.IsNull() || path == nullptr || path[0] == 0) return false;
  try {
    std::ofstream out(std::filesystem::path(path), std::ios::binary);
    if (!out.is_open()) return false;
    BRepTools::Write(shape, out);
    return out.good();
  } catch (...) {
    return false;
  }
}

extern "C" bool occt2d_write_edge_brep(void* edge, const wchar_t* path)
{
  if (edge == nullptr) return false;
  const TopoDS_Shape shape = !as_edge(edge)->edge.IsNull() ? TopoDS_Shape(as_edge(edge)->edge) : as_edge(edge)->display_shape;
  return write_brep_shape(shape, path);
}

extern "C" bool occt2d_write_wire_brep(void* wire, const wchar_t* path)
{
  if (wire == nullptr) return false;
  TopoDS_Shape shape;
  if (!as_wire(wire)->display_shapes.empty()) {
    shape = make_display_compound(as_wire(wire)->display_shapes);
  } else if (!as_wire(wire)->wire.IsNull()) {
    shape = TopoDS_Shape(as_wire(wire)->wire);
  }
  return write_brep_shape(shape, path);
}

extern "C" void* occt2d_read_shape_brep(const wchar_t* path)
{
  if (path == nullptr || path[0] == 0) return nullptr;
  try {
    std::ifstream in(std::filesystem::path(path), std::ios::binary);
    if (!in.is_open()) return nullptr;
    TopoDS_Shape shape;
    BRep_Builder builder;
    BRepTools::Read(shape, in, builder);
    if (shape.IsNull()) return nullptr;
    return new V2dShape{shape};
  } catch (...) {
    return nullptr;
  }
}

static bool write_dxf_shape(const TopoDS_Shape& shape, const wchar_t* path)
{
  if (shape.IsNull() || path == nullptr || path[0] == 0) return false;
  try {
    std::ofstream out(std::filesystem::path(path), std::ios::binary);
    if (!out.is_open()) return false;
    out.setf(std::ios::fixed);
    out.precision(8);
    out << "0\nSECTION\n2\nHEADER\n9\n$ACADVER\n1\nAC1009\n0\nENDSEC\n";
    out << "0\nSECTION\n2\nTABLES\n";
    out << "0\nTABLE\n2\nLAYER\n70\n1\n";
    out << "0\nLAYER\n2\n0\n70\n0\n62\n7\n6\nCONTINUOUS\n";
    out << "0\nENDTAB\n0\nENDSEC\n";
    out << "0\nSECTION\n2\nENTITIES\n";
    const int count = write_dxf_shape_edges(out, shape);
    out << "0\nENDSEC\n0\nEOF\n";
    return count > 0 && out.good();
  } catch (...) {
    return false;
  }
}

