extern "C" void* occt2d_read_shape_dxf(const wchar_t* path)
{
  if (path == nullptr || path[0] == 0) return nullptr;
  try {
    std::ifstream in(std::filesystem::path(path), std::ios::binary);
    if (!in.is_open()) return nullptr;
    std::vector<std::pair<int, std::string>> pairs;
    std::string code_line;
    std::string value_line;
    while (std::getline(in, code_line) && std::getline(in, value_line)) {
      pairs.push_back(std::make_pair(to_int_ascii(trim_ascii(code_line)), trim_ascii(value_line)));
    }

    TopoDS_Compound compound;
    BRep_Builder builder;
    builder.MakeCompound(compound);
    bool has_shape = false;

    for (std::vector<std::pair<int, std::string>>::size_type i = 0; i < pairs.size();) {
      if (pairs[i].first != 0) {
        ++i;
        continue;
      }
      const std::string type = upper_ascii(pairs[i].second);

      if (type == "LINE") {
        double x1 = 0.0, y1 = 0.0, x2 = 0.0, y2 = 0.0;
        std::vector<std::pair<int, std::string>>::size_type j = i + 1;
        for (; j < pairs.size() && pairs[j].first != 0; ++j) {
          if (pairs[j].first == 10) x1 = to_double_ascii(pairs[j].second);
          else if (pairs[j].first == 20) y1 = to_double_ascii(pairs[j].second);
          else if (pairs[j].first == 11) x2 = to_double_ascii(pairs[j].second);
          else if (pairs[j].first == 21) y2 = to_double_ascii(pairs[j].second);
        }
        add_edge_to_compound(builder, compound, gp_Pnt(x1, y1, 0.0), gp_Pnt(x2, y2, 0.0));
        has_shape = true;
        i = j;
      } else if (type == "CIRCLE" || type == "ARC") {
        double cx = 0.0, cy = 0.0, radius = 0.0, start_deg = 0.0, end_deg = 360.0;
        std::vector<std::pair<int, std::string>>::size_type j = i + 1;
        for (; j < pairs.size() && pairs[j].first != 0; ++j) {
          if (pairs[j].first == 10) cx = to_double_ascii(pairs[j].second);
          else if (pairs[j].first == 20) cy = to_double_ascii(pairs[j].second);
          else if (pairs[j].first == 40) radius = to_double_ascii(pairs[j].second);
          else if (pairs[j].first == 50) start_deg = to_double_ascii(pairs[j].second);
          else if (pairs[j].first == 51) end_deg = to_double_ascii(pairs[j].second);
        }
        std::vector<gp_Pnt> points = make_arc_points(cx, cy, radius, start_deg, end_deg, type == "CIRCLE" ? 96 : 48);
        add_polyline_to_compound(builder, compound, points, type == "CIRCLE");
        if (!points.empty()) has_shape = true;
        i = j;
      } else if (type == "LWPOLYLINE") {
        int flags = 0;
        std::vector<gp_Pnt> points;
        double pending_x = 0.0;
        bool has_x = false;
        std::vector<std::pair<int, std::string>>::size_type j = i + 1;
        for (; j < pairs.size() && pairs[j].first != 0; ++j) {
          if (pairs[j].first == 70) flags = to_int_ascii(pairs[j].second);
          else if (pairs[j].first == 10) {
            pending_x = to_double_ascii(pairs[j].second);
            has_x = true;
          } else if (pairs[j].first == 20 && has_x) {
            points.push_back(gp_Pnt(pending_x, to_double_ascii(pairs[j].second), 0.0));
            has_x = false;
          }
        }
        add_polyline_to_compound(builder, compound, points, (flags & 1) != 0);
        if (points.size() >= 2) has_shape = true;
        i = j;
      } else if (type == "POLYLINE") {
        std::vector<gp_Pnt> points;
        bool closed = false;
        std::vector<std::pair<int, std::string>>::size_type j = i + 1;
        for (; j < pairs.size();) {
          if (pairs[j].first == 70) {
            closed = (to_int_ascii(pairs[j].second) & 1) != 0;
            ++j;
          } else if (pairs[j].first == 0 && upper_ascii(pairs[j].second) == "VERTEX") {
            double x = 0.0, y = 0.0;
            ++j;
            for (; j < pairs.size() && pairs[j].first != 0; ++j) {
              if (pairs[j].first == 10) x = to_double_ascii(pairs[j].second);
              else if (pairs[j].first == 20) y = to_double_ascii(pairs[j].second);
            }
            points.push_back(gp_Pnt(x, y, 0.0));
          } else if (pairs[j].first == 0 && upper_ascii(pairs[j].second) == "SEQEND") {
            ++j;
            break;
          } else if (pairs[j].first == 0) {
            break;
          } else {
            ++j;
          }
        }
        add_polyline_to_compound(builder, compound, points, closed);
        if (points.size() >= 2) has_shape = true;
        i = j;
      } else {
        ++i;
      }
    }

    if (!has_shape) return nullptr;
    return new V2dShape{TopoDS_Shape(compound)};
  } catch (...) {
    return nullptr;
  }
}

static std::string occt2d_narrow_file_path(const wchar_t* path)
{
  if (path == nullptr || path[0] == 0) return std::string();
  try {
    return std::filesystem::path(path).string();
  } catch (...) {
    return std::string();
  }
}

extern "C" void* occt2d_read_shape_step(const wchar_t* path)
{
  const std::string file_name = occt2d_narrow_file_path(path);
  if (file_name.empty()) return nullptr;
  try {
    STEPControl_Reader reader;
    if (reader.ReadFile(file_name.c_str()) != IFSelect_RetDone) return nullptr;
    if (reader.TransferRoots() <= 0) return nullptr;
    TopoDS_Shape shape = reader.OneShape();
    if (shape.IsNull()) return nullptr;
    return new V2dShape{shape};
  } catch (...) {
    return nullptr;
  }
}

extern "C" void* occt2d_read_shape_iges(const wchar_t* path)
{
  const std::string file_name = occt2d_narrow_file_path(path);
  if (file_name.empty()) return nullptr;
  try {
    IGESControl_Reader reader;
    if (reader.ReadFile(file_name.c_str()) != IFSelect_RetDone) return nullptr;
    if (reader.TransferRoots() <= 0) return nullptr;
    TopoDS_Shape shape = reader.OneShape();
    if (shape.IsNull()) return nullptr;
    return new V2dShape{shape};
  } catch (...) {
    return nullptr;
  }
}

