static Draw_Color occt2d_draw_color_from_int(int color)
{
  if (color < static_cast<int>(Draw_blanc) || color > static_cast<int>(Draw_corail)) {
    color = static_cast<int>(Draw_blanc);
  }
  return Draw_Color(static_cast<Draw_ColorKind>(color));
}

