extern "C" int occt2d_draw_last_pick(int field)
{
  try {
    int view = 0, x = 0, y = 0, button = 0;
    Draw::LastPick(view, x, y, button);
    if (field == 1) return view;
    if (field == 2) return x;
    if (field == 3) return y;
    if (field == 4) return button;
    return 0;
  } catch (...) { return 0; }
}

extern "C" bool occt2d_draw_load_standard_commands(void* interp, int command_set)
{
  try {
    if (interp == nullptr || as_draw_interpretor(interp)->value == nullptr) return false;
    Draw_Interpretor& di = *as_draw_interpretor(interp)->value;
    if (command_set == 1) Draw::BasicCommands(di);
    else if (command_set == 2) Draw::MessageCommands(di);
    else if (command_set == 3) Draw::VariableCommands(di);
    else if (command_set == 4) Draw::GraphicCommands(di);
    else if (command_set == 5) Draw::PloadCommands(di);
    else if (command_set == 6) Draw::UnitCommands(di);
    else Draw::Commands(di);
    return true;
  } catch (...) { return false; }
}

static Draw_Color& occt2d_drawtrsurf_param_color_ref(int field)
{
  DrawTrSurf_Params& params = occt2d_drawtrsurf_params();
  switch (field) {
  case 1: return params.PntColor;
  case 2: return params.CurvColor;
  case 3: return params.BoundsColor;
  case 4: return params.IsosColor;
  case 5: return params.PolesColor;
  case 6: return params.KnotsColor;
  default: return params.CurvColor;
  }
}

static Draw_MarkerShape& occt2d_drawtrsurf_param_marker_ref(int field)
{
  DrawTrSurf_Params& params = occt2d_drawtrsurf_params();
  switch (field) {
  case 1: return params.PntMarker;
  case 2: return params.KnotsMarker;
  default: return params.PntMarker;
  }
}

static bool& occt2d_drawtrsurf_param_bool_ref(int field)
{
  DrawTrSurf_Params& params = occt2d_drawtrsurf_params();
  switch (field) {
  case 1: return params.IsShowPoles;
  case 2: return params.IsShowKnots;
  case 3: return params.NeedKnotsIsos;
  default: return params.IsShowPoles;
  }
}

static int& occt2d_drawtrsurf_param_int_ref(int field)
{
  DrawTrSurf_Params& params = occt2d_drawtrsurf_params();
  switch (field) {
  case 1: return params.KnotsSize;
  case 2: return params.Discret;
  case 3: return params.DrawMode;
  case 4: return params.NbUIsos;
  case 5: return params.NbVIsos;
  default: return params.Discret;
  }
}

