#include <TopLoc_Location.hxx>
#include <TopExp_Explorer.hxx>
#include <Bnd_Box.hxx>
#include <Bnd_Box2d.hxx>
#include <BRep_Tool.hxx>
#include <BRepTools.hxx>
#include <BRepBndLib.hxx>

struct V3dLocation { TopLoc_Location value; };
struct V3dBndBox { Bnd_Box value; };
struct V2dBndBox2d { Bnd_Box2d value; };
struct V3dExplorer { TopExp_Explorer value; };
struct V3dEdgeCurve {
  occ::handle<Geom_Curve> curve;
  double first = 0.0;
  double last = 0.0;
  TopLoc_Location loc;
};
struct V3dFaceSurface {
  occ::handle<Geom_Surface> surface;
  TopLoc_Location loc;
  bool reversed = false;
};
struct V3dFaceUVBounds {
  double u1 = 0.0;
  double u2 = 0.0;
  double v1 = 0.0;
  double v2 = 0.0;
};

static V3dLocation* as_loc(void* p) { return static_cast<V3dLocation*>(p); }
static V3dBndBox* as_bnd_box(void* p) { return static_cast<V3dBndBox*>(p); }
static V2dBndBox2d* as_bnd_box2d(void* p) { return static_cast<V2dBndBox2d*>(p); }
static V3dExplorer* as_explorer(void* p) { return static_cast<V3dExplorer*>(p); }
static V3dEdgeCurve* as_edge_curve3d(void* p) { return static_cast<V3dEdgeCurve*>(p); }
static V3dFaceSurface* as_face_surface3d(void* p) { return static_cast<V3dFaceSurface*>(p); }
static V3dFaceUVBounds* as_face_uv(void* p) { return static_cast<V3dFaceUVBounds*>(p); }

extern "C" void* occt2d_loc_new()
{
  try { return new V3dLocation{TopLoc_Location()}; } catch (...) { return nullptr; }
}

extern "C" void* occt2d_loc_from_trsf(void* trsf)
{
  try { return trsf == nullptr ? nullptr : new V3dLocation{TopLoc_Location(as_trsf3d(trsf)->value)}; } catch (...) { return nullptr; }
}

extern "C" bool occt2d_loc_is_identity(void* loc)
{
  try { return loc != nullptr && as_loc(loc)->value.IsIdentity(); } catch (...) { return true; }
}

extern "C" bool occt2d_loc_set_identity(void* loc)
{
  try {
    if (loc == nullptr) return false;
    as_loc(loc)->value.Identity();
    return true;
  } catch (...) { return false; }
}

