extern "C" void* occt2d_brep_tool_point(void* vertex_shape)
{
  try {
    if (vertex_shape == nullptr || as_shape(vertex_shape)->shape.IsNull()) return nullptr;
    return new VOcctPnt{BRep_Tool::Pnt(TopoDS::Vertex(as_shape(vertex_shape)->shape))};
  } catch (...) { return nullptr; }
}

extern "C" double occt2d_brep_tool_tolerance(void* shape)
{
  try {
    if (shape == nullptr || as_shape(shape)->shape.IsNull()) return 0.0;
    const TopoDS_Shape& value = as_shape(shape)->shape;
    switch (value.ShapeType()) {
      case TopAbs_VERTEX: return BRep_Tool::Tolerance(TopoDS::Vertex(value));
      case TopAbs_EDGE: return BRep_Tool::Tolerance(TopoDS::Edge(value));
      case TopAbs_FACE: return BRep_Tool::Tolerance(TopoDS::Face(value));
      default: return 0.0;
    }
  } catch (...) { return 0.0; }
}

extern "C" bool occt2d_brep_tool_is_degenerated(void* edge_shape)
{
  try { return (edge_shape == nullptr || as_shape(edge_shape)->shape.IsNull()) ? false : BRep_Tool::Degenerated(TopoDS::Edge(as_shape(edge_shape)->shape)); } catch (...) { return false; }
}

extern "C" void* occt2d_brep_tool_edge_curve(void* edge_shape)
{
  try {
    if (edge_shape == nullptr || as_shape(edge_shape)->shape.IsNull()) return nullptr;
    const TopoDS_Edge edge = TopoDS::Edge(as_shape(edge_shape)->shape);
    TopLoc_Location loc;
    double first = 0.0;
    double last = 0.0;
    occ::handle<Geom_Curve> curve = BRep_Tool::Curve(edge, loc, first, last);
    if (curve.IsNull()) return nullptr;
    V3dEdgeCurve* result = new V3dEdgeCurve;
    result->curve = curve;
    result->first = first;
    result->last = last;
    result->loc = loc;
    return result;
  } catch (...) { return nullptr; }
}

extern "C" void* occt2d_brep_tool_face_surface(void* face_shape)
{
  try {
    if (face_shape == nullptr || as_shape(face_shape)->shape.IsNull()) return nullptr;
    const TopoDS_Face face = TopoDS::Face(as_shape(face_shape)->shape);
    TopLoc_Location loc;
    occ::handle<Geom_Surface> surface = BRep_Tool::Surface(face, loc);
    if (surface.IsNull()) return nullptr;
    V3dFaceSurface* result = new V3dFaceSurface;
    result->surface = surface;
    result->loc = loc;
    result->reversed = (face.Orientation() == TopAbs_REVERSED);
    return result;
  } catch (...) { return nullptr; }
}

extern "C" void* occt2d_brep_tools_uv_bounds(void* face_shape)
{
  try {
    if (face_shape == nullptr || as_shape(face_shape)->shape.IsNull()) return nullptr;
    V3dFaceUVBounds* bounds = new V3dFaceUVBounds;
    BRepTools::UVBounds(TopoDS::Face(as_shape(face_shape)->shape), bounds->u1, bounds->u2, bounds->v1, bounds->v2);
    return bounds;
  } catch (...) { return nullptr; }
}

