struct V3dFillet { std::unique_ptr<BRepFilletAPI_MakeFillet> value; };
struct V3dChamfer { std::unique_ptr<BRepFilletAPI_MakeChamfer> value; };
struct V3dAdaptorCurve { std::unique_ptr<BRepAdaptor_Curve> value; };
struct V3dAdaptorSurface { std::unique_ptr<BRepAdaptor_Surface> value; };

static V3dFillet* as_fillet3d(void* p) { return static_cast<V3dFillet*>(p); }
static V3dChamfer* as_chamfer3d(void* p) { return static_cast<V3dChamfer*>(p); }
static V3dAdaptorCurve* as_adaptor_curve3d(void* p) { return static_cast<V3dAdaptorCurve*>(p); }
static V3dAdaptorSurface* as_adaptor_surface3d(void* p) { return static_cast<V3dAdaptorSurface*>(p); }

extern "C" void* occt2d_fillet_new(void* shape)
{
  try {
    if (shape == nullptr || as_shape(shape)->shape.IsNull()) return nullptr;
    V3dFillet* obj = new V3dFillet;
    obj->value = std::make_unique<BRepFilletAPI_MakeFillet>(as_shape(shape)->shape);
    return obj;
  } catch (...) { return nullptr; }
}

