{
  try {
    if (fillet == nullptr || as_fillet3d(fillet)->value == nullptr || edge_shape == nullptr || as_shape(edge_shape)->shape.IsNull()) return false;
    as_fillet3d(fillet)->value->Add(radius, TopoDS::Edge(as_shape(edge_shape)->shape));
    return true;
  } catch (...) { return false; }
}

