{
  try {
    if (chamfer == nullptr || as_chamfer3d(chamfer)->value == nullptr || edge_shape == nullptr || as_shape(edge_shape)->shape.IsNull()) return false;
    as_chamfer3d(chamfer)->value->Add(distance, TopoDS::Edge(as_shape(edge_shape)->shape));
    return true;
  } catch (...) { return false; }
}

