extern "C" int occt2d_shape_contents(void* shape, int what)
{
  try {
    if (shape == nullptr || as_shape(shape)->shape.IsNull()) return 0;
    ShapeAnalysis_ShapeContents contents;
    contents.Perform(as_shape(shape)->shape);
    switch (what) {
      case 0: return contents.NbSolids();
      case 1: return contents.NbShells();
      case 2: return contents.NbFaces();
      case 3: return contents.NbEdges();
      case 4: return contents.NbVertices();
      case 5: return contents.NbFreeWires();
      case 6: return contents.NbFreeEdges();
      case 7: return contents.NbSolidsWithVoids();
      case 8: return contents.NbSharedSolids();
      default: return 0;
    }
  } catch (...) { return 0; }
}

