#include <GCPnts_UniformAbscissa.hxx>
#include <GCPnts_QuasiUniformDeflection.hxx>
#include <GCPnts_AbscissaPoint.hxx>
#include <Geom_Line.hxx>
#include <Geom_Circle.hxx>

struct V3dSampler
{
  std::unique_ptr<BRepAdaptor_Curve> curve;
  std::unique_ptr<GCPnts_UniformAbscissa> ua;
  std::unique_ptr<GCPnts_QuasiUniformDeflection> qud;
};

static V3dSampler* as_sampler3d(void* p) { return static_cast<V3dSampler*>(p); }

extern "C" void* occt2d_sampler_abscissa_new(void* edge_shape, int nb_points)
{
  try {
    if (edge_shape == nullptr || as_shape(edge_shape)->shape.IsNull() || nb_points < 2) return nullptr;
    V3dSampler* obj = new V3dSampler;
    obj->curve = std::make_unique<BRepAdaptor_Curve>(TopoDS::Edge(as_shape(edge_shape)->shape));
    obj->ua = std::make_unique<GCPnts_UniformAbscissa>(*obj->curve, nb_points);
    return obj;
  } catch (...) { return nullptr; }
}

extern "C" void* occt2d_sampler_deflection_new(void* edge_shape, double deflection)
{
  try {
    if (edge_shape == nullptr || as_shape(edge_shape)->shape.IsNull() || deflection <= 0.0) return nullptr;
    V3dSampler* obj = new V3dSampler;
    obj->curve = std::make_unique<BRepAdaptor_Curve>(TopoDS::Edge(as_shape(edge_shape)->shape));
    obj->qud = std::make_unique<GCPnts_QuasiUniformDeflection>(*obj->curve, deflection);
    return obj;
  } catch (...) { return nullptr; }
}

extern "C" bool occt2d_sampler_is_done(void* sampler)
{
  try {
    if (sampler == nullptr) return false;
    V3dSampler* s = as_sampler3d(sampler);
    if (s->ua) return s->ua->IsDone();
    if (s->qud) return s->qud->IsDone();
    return false;
  } catch (...) { return false; }
}

extern "C" int occt2d_sampler_nb_points(void* sampler)
{
  try {
    if (sampler == nullptr) return 0;
    V3dSampler* s = as_sampler3d(sampler);
    if (s->ua && s->ua->IsDone()) return s->ua->NbPoints();
    if (s->qud && s->qud->IsDone()) return s->qud->NbPoints();
    return 0;
  } catch (...) { return 0; }
}

extern "C" double occt2d_sampler_parameter(void* sampler, int index)
{
  try {
    if (sampler == nullptr) return 0.0;
    V3dSampler* s = as_sampler3d(sampler);
    if (s->ua && s->ua->IsDone() && index >= 1 && index <= s->ua->NbPoints()) return s->ua->Parameter(index);
    if (s->qud && s->qud->IsDone() && index >= 1 && index <= s->qud->NbPoints()) return s->qud->Parameter(index);
    return 0.0;
  } catch (...) { return 0.0; }
}

extern "C" void* occt2d_sampler_point(void* sampler, int index)
{
  try {
    if (sampler == nullptr) return nullptr;
    V3dSampler* s = as_sampler3d(sampler);
    if (s->ua && s->ua->IsDone() && index >= 1 && index <= s->ua->NbPoints())
      return new VOcctPnt{s->curve->Value(s->ua->Parameter(index))};
    if (s->qud && s->qud->IsDone() && index >= 1 && index <= s->qud->NbPoints())
      return new VOcctPnt{s->qud->Value(index)};
    return nullptr;
  } catch (...) { return nullptr; }
}

extern "C" double occt2d_curve_length(void* edge_shape)
{
  try {
    if (edge_shape == nullptr || as_shape(edge_shape)->shape.IsNull()) return 0.0;
    BRepAdaptor_Curve curve(TopoDS::Edge(as_shape(edge_shape)->shape));
    return GCPnts_AbscissaPoint::Length(curve);
  } catch (...) { return 0.0; }
}

extern "C" void* occt2d_geom_line_new(double px, double py, double pz, double dx, double dy, double dz)
{
  try {
    gp_Dir dir(dx, dy, dz);
    return new V3dGeomCurve{occ::handle<Geom_Curve>(new Geom_Line(gp_Pnt(px, py, pz), dir))};
  } catch (...) { return nullptr; }
}

extern "C" void* occt2d_geom_circle_new(double px, double py, double pz, double nx, double ny, double nz, double radius)
{
  try {
    if (radius <= 0.0) return nullptr;
    gp_Ax2 axis(gp_Pnt(px, py, pz), gp_Dir(nx, ny, nz));
    return new V3dGeomCurve{occ::handle<Geom_Curve>(new Geom_Circle(axis, radius))};
  } catch (...) { return nullptr; }
}

#include <STEPControl_Writer.hxx>
#include <Interface_Static.hxx>

extern "C" bool occt2d_write_shape_step(const wchar_t* path, void* shape, int model_type)
{
  const std::string file_name = occt2d_narrow_file_path(path);
  if (file_name.empty() || shape == nullptr || as_shape(shape)->shape.IsNull()) return false;
  try {
    STEPControl_StepModelType mode = STEPControl_AsIs;
    switch (model_type) {
      case 1: mode = STEPControl_ManifoldSolidBrep; break;
      case 2: mode = STEPControl_BrepWithVoids; break;
      case 3: mode = STEPControl_FacetedBrep; break;
      case 4: mode = STEPControl_FacetedBrepAndBrepWithVoids; break;
      case 5: mode = STEPControl_ShellBasedSurfaceModel; break;
      case 6: mode = STEPControl_GeometricCurveSet; break;
      case 7: mode = STEPControl_Hybrid; break;
      default: mode = STEPControl_AsIs; break;
    }
    STEPControl_Writer writer;
    if (writer.Transfer(as_shape(shape)->shape, mode) != IFSelect_RetDone) return false;
    return writer.Write(file_name.c_str()) == IFSelect_RetDone;
  } catch (...) { return false; }
}

