#include <IGESControl_Writer.hxx>
#include <StlAPI_Writer.hxx>
#include <StlAPI_Reader.hxx>

extern "C" bool occt2d_write_shape_iges(const wchar_t* path, void* shape, const wchar_t* unit)
{
  const std::string file_name = occt2d_narrow_file_path(path);
  if (file_name.empty() || shape == nullptr || as_shape(shape)->shape.IsNull()) return false;
  try {
    std::string u = occt2d_narrow_file_path(unit);
    IGESControl_Writer writer(u.empty() ? "MM" : u.c_str(), 0);
    if (!writer.AddShape(as_shape(shape)->shape)) return false;
    writer.ComputeModel();
    return writer.Write(file_name.c_str());
  } catch (...) { return false; }
}

extern "C" bool occt2d_write_shape_stl(const wchar_t* path, void* shape, bool ascii)
{
  const std::string file_name = occt2d_narrow_file_path(path);
  if (file_name.empty() || shape == nullptr || as_shape(shape)->shape.IsNull()) return false;
  try {
    StlAPI_Writer writer;
    writer.ASCIIMode() = ascii;
    return writer.Write(as_shape(shape)->shape, file_name.c_str());
  } catch (...) { return false; }
}

extern "C" void* occt2d_read_shape_stl(const wchar_t* path)
{
  const std::string file_name = occt2d_narrow_file_path(path);
  if (file_name.empty()) return nullptr;
  try {
    StlAPI_Reader reader;
    TopoDS_Shape shape;
    if (!reader.Read(shape, file_name.c_str())) return nullptr;
    if (shape.IsNull()) return nullptr;
    return new V2dShape{shape};
  } catch (...) { return nullptr; }
}

