// ---- B8 reinforcement: TDF_Label entries, reusing V3dOcafLabel ----
// Creates an empty label placeholder. Real labels come from XCAFDoc shape
// tool (NewShape / AddShape) and are passed back in. The returned pointer has
// exactly the same type as occt2d_ocaf_label_find_child / new_child results,
// so it works directly as the object pointer of the handwritten OCCT label
// class (object type "ocaf_label") and shares the same free path.
extern "C" void* occt2d_label_new()
{
  try { return new V3dOcafLabel{ TDF_Label() }; } catch (...) { return nullptr; }
}
extern "C" bool occt2d_label_is_same(void* a, void* b)
{
  try {
    return a && b ? as_ocaf_label(a)->value.IsEqual(as_ocaf_label(b)->value) : false;
  } catch (...) { return false; }
}

extern "C" void occt2d_ocaf_set_integer(void* label, int value)
{
  try { if (label != nullptr) TDataStd_Integer::Set(as_ocaf_label(label)->value, value); } catch (...) {}
}

extern "C" int occt2d_ocaf_get_integer(void* label)
{
  try {
    if (label == nullptr) return 0;
    occ::handle<TDataStd_Integer> attr;
    if (as_ocaf_label(label)->value.FindAttribute(TDataStd_Integer::GetID(), attr) && !attr.IsNull()) return attr->Get();
    return 0;
  } catch (...) { return 0; }
}

