extern "C" void occt2d_ocaf_set_string(void* label, const wchar_t* value)
{
  try {
    if (label == nullptr) return;
    const std::string narrow = occt2d_narrow_file_path(value);
    TDataStd_AsciiString::Set(as_ocaf_label(label)->value, TCollection_AsciiString(narrow.c_str()));
  } catch (...) {}
}

extern "C" const wchar_t* occt2d_ocaf_get_string(void* label)
{
  try {
    if (label == nullptr) return L"";
    occ::handle<TDataStd_AsciiString> attr;
    if (as_ocaf_label(label)->value.FindAttribute(TDataStd_AsciiString::GetID(), attr) && !attr.IsNull()) return ascii_to_wide(attr->Get());
    return L"";
  } catch (...) { return L""; }
}

extern "C" bool occt2d_ocaf_set_name(void* label, const wchar_t* value)
{
  try {
    if (label == nullptr) return false;
    const std::string narrow = occt2d_narrow_file_path(value);
    TDataStd_Name::Set(as_ocaf_label(label)->value, TCollection_ExtendedString(narrow.c_str(), true));
    return true;
  } catch (...) { return false; }
}

// Read back the TDataStd_Name attribute written by occt2d_ocaf_set_name.
// Returns an empty string when the label carries no name.
// NOTE: ToWideString() points into the attribute's own buffer, so it must be
// copied before the handle goes out of scope -- hence the thread_local cache.
// The returned pointer is valid until the next call on the same thread.
extern "C" const wchar_t* occt2d_ocaf_get_name(void* label)
{
  try {
    if (label == nullptr) return L"";
    occ::handle<TDataStd_Name> attr;
    if (as_ocaf_label(label)->value.FindAttribute(TDataStd_Name::GetID(), attr)
        && !attr.IsNull())
    {
      static thread_local std::wstring cache;
      cache = attr->Get().ToWideString();
      return cache.c_str();
    }
    return L"";
  } catch (...) { return L""; }
}

