extern "C" void occt2d_ocaf_set_shape(void* label, void* shape)
{
  try {
    if (label == nullptr || shape == nullptr || as_shape(shape)->shape.IsNull()) return;
    TNaming_Builder builder(as_ocaf_label(label)->value);
    builder.Generated(as_shape(shape)->shape);
  } catch (...) {}
}

extern "C" void* occt2d_ocaf_get_shape(void* label)
{
  try {
    if (label == nullptr) return nullptr;
    occ::handle<TNaming_NamedShape> attr;
    if (as_ocaf_label(label)->value.FindAttribute(TNaming_NamedShape::GetID(), attr) && !attr.IsNull()) {
      TopoDS_Shape shape = TNaming_Tool::GetShape(attr);
      if (!shape.IsNull()) return new_shape_wrapper(shape);
    }
    return nullptr;
  } catch (...) { return nullptr; }
}

