namespace {
std::wstring g_occt2d_gl_wbuf;
const wchar_t* Occt2dGlFromAnsi(const char* s) {
  g_occt2d_gl_wbuf.clear();
  if (s == nullptr) return L"";
  int n = ::MultiByteToWideChar(CP_ACP, 0, s, -1, nullptr, 0);
  if (n <= 1) return L"";
  g_occt2d_gl_wbuf.resize((size_t)(n - 1));
  ::MultiByteToWideChar(CP_ACP, 0, s, -1, &g_occt2d_gl_wbuf[0], n);
  return g_occt2d_gl_wbuf.c_str();
}
std::string Occt2dGlToUtf8(const wchar_t* s) {
  if (s == nullptr) return std::string();
  int n = ::WideCharToMultiByte(CP_UTF8, 0, s, -1, nullptr, 0, nullptr, nullptr);
  if (n <= 1) return std::string();
  std::string r((size_t)(n - 1), (char)0);
  ::WideCharToMultiByte(CP_UTF8, 0, s, -1, &r[0], n, nullptr, nullptr);
  return r;
}
void* Occt2dGlProc(const char* name) {
  void* p = reinterpret_cast<void*>(::wglGetProcAddress(name));
  if (p == nullptr || p == (void*)1 || p == (void*)2 || p == (void*)3 || p == (void*)-1) {
    static HMODULE mod = ::GetModuleHandleW(L"opengl32.dll");
    if (mod == nullptr) mod = ::LoadLibraryW(L"opengl32.dll");
    p = mod != nullptr ? reinterpret_cast<void*>(::GetProcAddress(mod, name)) : nullptr;
  }
  return p;
}
}

