extern "C" const wchar_t* occt2d_gl_get_shader_info_log(unsigned int shader)
{
  if (g_glx.p_glGetShaderiv == nullptr) return L"";
  GLint len = 0; g_glx.p_glGetShaderiv((GLuint)shader, GL_INFO_LOG_LENGTH, &len);
  if (len <= 1) return L"";
  std::string buf((size_t)len, (char)0);
  GLsizei written = 0; g_glx.p_glGetShaderInfoLog((GLuint)shader, (GLsizei)len, &written, &buf[0]);
  if (written > 0) buf.resize((size_t)written);
  return Occt2dGlFromAnsi(buf.c_str());
}

extern "C" const wchar_t* occt2d_gl_get_program_info_log(unsigned int program)
{
  if (g_glx.p_glGetProgramiv == nullptr) return L"";
  GLint len = 0; g_glx.p_glGetProgramiv((GLuint)program, GL_INFO_LOG_LENGTH, &len);
  if (len <= 1) return L"";
  std::string buf((size_t)len, (char)0);
  GLsizei written = 0; g_glx.p_glGetProgramInfoLog((GLuint)program, (GLsizei)len, &written, &buf[0]);
  if (written > 0) buf.resize((size_t)written);
  return Occt2dGlFromAnsi(buf.c_str());
}

extern "C" void occt2d_gl_read_pixels(int x, int y, int width, int height, unsigned int format, unsigned int type, void* data)
{
  glReadPixels((GLint)x, (GLint)y, (GLsizei)width, (GLsizei)height, (GLenum)format, (GLenum)type, data);
}

extern "C" const wchar_t* occt2d_gl_read_pixel_text(int x, int y)
{
  unsigned char px[4] = { 0, 0, 0, 0 };
  glReadPixels((GLint)x, (GLint)y, 1, 1, GL_RGBA, GL_UNSIGNED_BYTE, px);
  wchar_t buf[64] = {};
  ::swprintf(buf, 64, L"%u,%u,%u,%u", (unsigned)px[0], (unsigned)px[1], (unsigned)px[2], (unsigned)px[3]);
  g_occt2d_gl_wbuf = buf;
  return g_occt2d_gl_wbuf.c_str();
}

extern "C" void occt2d_gl_shader_source(unsigned int shader, const wchar_t* source)
{
  if (g_glx.p_glShaderSource == nullptr) return;
  std::string src = Occt2dGlToUtf8(source);
  const char* arr = src.c_str();
  const GLint len = (GLint)src.size();
  g_glx.p_glShaderSource((GLuint)shader, 1, &arr, &len);
}

