// ===== OCCT OpenGl_Context wrapper (non-owning reference obtained from OpenGl_GraphicDriver) =====
static OpenGl_Context* as_opengl_context(void* p) { return static_cast<OpenGl_Context*>(p); }

extern "C" void* occt2d_opengl_driver_shared_context(void* driver)
{
  try
  {
    if (driver == nullptr || as_graphic_driver(driver)->value.IsNull()) return nullptr;
    return as_graphic_driver(driver)->value->GetSharedContext().get();
  }
  catch (...) { return nullptr; }
}
extern "C" bool occt2d_opengl_context_is_valid(void* ctx)
{
  try { return ctx != nullptr && as_opengl_context(ctx)->IsValid(); } catch (...) { return false; }
}
extern "C" int occt2d_opengl_context_version_major(void* ctx)
{
  try { return ctx != nullptr ? as_opengl_context(ctx)->VersionMajor() : 0; } catch (...) { return 0; }
}
extern "C" int occt2d_opengl_context_version_minor(void* ctx)
{
  try { return ctx != nullptr ? as_opengl_context(ctx)->VersionMinor() : 0; } catch (...) { return 0; }
}
extern "C" int occt2d_opengl_context_graphics_library(void* ctx)
{
  try { return ctx != nullptr ? static_cast<int>(as_opengl_context(ctx)->GraphicsLibrary()) : 0; } catch (...) { return 0; }
}
extern "C" const wchar_t* occt2d_opengl_context_vendor(void* ctx)
{
  try { return ctx != nullptr ? ascii_to_wide(as_opengl_context(ctx)->Vendor()) : L""; } catch (...) { return L""; }
}
extern "C" int occt2d_opengl_context_max_texture_size(void* ctx)
{
  try { return ctx != nullptr ? as_opengl_context(ctx)->MaxTextureSize() : 0; } catch (...) { return 0; }
}
extern "C" int occt2d_opengl_context_max_texture_units_ffp(void* ctx)
{
  try { return ctx != nullptr ? as_opengl_context(ctx)->MaxTextureUnitsFFP() : 0; } catch (...) { return 0; }
}
