// ==== BEGIN SUPPORT ARRAY1 ====
// 1-D array support: OCCT 8.0 TColStd_Array1OfReal / TColgp_Array1OfPnt etc. are
// aliases of NCollection_Array1<T>. A template cannot be wrapped as a Volcano
// class, so VArray1<T> holds a value-semantic array (copy == deep copy) and lets
// the generated layer map `const NCollection_Array1<T>&` parameters / returns to
// void* passing.
// NOTE: comments in this file MUST stay pure ASCII -- MSVC reads it as GBK and a
// UTF-8 Chinese comment can swallow the following line.
#include <NCollection_Array1.hxx>
#include <gp_Pnt.hxx>
#include <gp_Pnt2d.hxx>
#include <gp_Vec.hxx>
#include <gp_Vec2d.hxx>

template <class T>
struct VArray1
{
  NCollection_Array1<T> value;
};

template <class T>
static void* array1_new_impl(int lower, int upper)
{
  try { return new VArray1<T>{ NCollection_Array1<T>(lower, upper) }; }
  catch (...) { return nullptr; }
}

template <class T>
static void array1_free_impl(void* a) { delete static_cast<VArray1<T>*>(a); }

template <class T>
static int array1_lower_impl(void* a)
{
  return a ? static_cast<VArray1<T>*>(a)->value.Lower() : 0;
}

template <class T>
static int array1_upper_impl(void* a)
{
  return a ? static_cast<VArray1<T>*>(a)->value.Upper() : 0;
}

template <class T>
static int array1_length_impl(void* a)
{
  return a ? static_cast<VArray1<T>*>(a)->value.Length() : 0;
}

template <class T>
static void array1_set_impl(void* a, int i, const T& v)
{
  if (!a) return;
  VArray1<T>* w = static_cast<VArray1<T>*>(a);
  if (i < w->value.Lower() || i > w->value.Upper()) return;
  w->value.SetValue(i, v);
}

template <class T>
static T array1_get_impl(void* a, int i)
{
  if (!a) return T();
  VArray1<T>* w = static_cast<VArray1<T>*>(a);
  if (i < w->value.Lower() || i > w->value.Upper()) return T();
  return w->value.Value(i);
}

extern "C" void* occt2d_array1_real_new(int lower, int upper)
{ return array1_new_impl<double>(lower, upper); }
extern "C" void occt2d_array1_real_free(void* a)
{ array1_free_impl<double>(a); }
extern "C" int occt2d_array1_real_lower(void* a)
{ return array1_lower_impl<double>(a); }
extern "C" int occt2d_array1_real_upper(void* a)
{ return array1_upper_impl<double>(a); }
extern "C" int occt2d_array1_real_length(void* a)
{ return array1_length_impl<double>(a); }
extern "C" void occt2d_array1_real_set(void* a, int i, double v)
{ array1_set_impl<double>(a, i, v); }
extern "C" double occt2d_array1_real_get(void* a, int i)
{ return array1_get_impl<double>(a, i); }
extern "C" void* occt2d_array1_integer_new(int lower, int upper)
{ return array1_new_impl<int>(lower, upper); }
extern "C" void occt2d_array1_integer_free(void* a)
{ array1_free_impl<int>(a); }
extern "C" int occt2d_array1_integer_lower(void* a)
{ return array1_lower_impl<int>(a); }
extern "C" int occt2d_array1_integer_upper(void* a)
{ return array1_upper_impl<int>(a); }
extern "C" int occt2d_array1_integer_length(void* a)
{ return array1_length_impl<int>(a); }
extern "C" void occt2d_array1_integer_set(void* a, int i, int v)
{ array1_set_impl<int>(a, i, v); }
extern "C" int occt2d_array1_integer_get(void* a, int i)
{ return array1_get_impl<int>(a, i); }
