#ifndef OCCT2D_AS_GEN_DEFINED
#define OCCT2D_AS_GEN_DEFINED
template <class T>
static T* as_gen(void* p) { return static_cast<T*>(p); }
#endif
#ifndef OCCT2D_TRY_NEW_DEFINED
#define OCCT2D_TRY_NEW_DEFINED
#include <type_traits>
template <class V, class T, class... A>
static void* occt2d_try_new(A... a)
{
  if constexpr (std::is_abstract_v<T>) { return nullptr; }
  else { return static_cast<void*>(new V{ new T(a...) }); }
}
#endif
#ifndef OCCT2D_WRAP_HANDLE_DEFINED
#define OCCT2D_WRAP_HANDLE_DEFINED
template <class V, class H>
static void* occt2d_wrap_handle(H&& h)
{
  if (h.IsNull()) { return nullptr; }
  return static_cast<void*>(new V{ h });
}
#endif
#ifndef OCCT2D_TRY_NEW_VALUE_DEFINED
#define OCCT2D_TRY_NEW_VALUE_DEFINED
template <class V, class T, class... A>
static void* occt2d_try_new_value(A... a)
{
  if constexpr (std::is_abstract_v<T>) { return nullptr; }
  else { return static_cast<void*>(new V{ T(a...) }); }
}
#endif
#ifndef OCCT2D_WRAP_SHAPE_VALUE_DEFINED
#define OCCT2D_WRAP_SHAPE_VALUE_DEFINED
template <class W, class S>
static void* occt2d_wrap_shape_value(const S& s)
{
  if (s.IsNull()) { return nullptr; }
  return static_cast<void*>(new W{ s });
}
#endif
#ifndef OCCT2D_GEN_NARROW_DEFINED
#define OCCT2D_GEN_NARROW_DEFINED
#include <string>
static std::string occt2d_gen_narrow(const wchar_t* s)
{
  if (s == nullptr) { return std::string(); }
  std::string out;
  for (const wchar_t* p = s; *p != 0; ++p)
  {
    const unsigned int c = static_cast<unsigned int>(*p);
    if (c < 0x80u) { out.push_back(static_cast<char>(c)); }
    else if (c < 0x800u)
    {
      out.push_back(static_cast<char>(0xC0u | (c >> 6)));
      out.push_back(static_cast<char>(0x80u | (c & 0x3Fu)));
    }
    else
    {
      out.push_back(static_cast<char>(0xE0u | (c >> 12)));
      out.push_back(static_cast<char>(0x80u | ((c >> 6) & 0x3Fu)));
      out.push_back(static_cast<char>(0x80u | (c & 0x3Fu)));
    }
  }
  return out;
}
#endif
